-- PostgreSQL port of db/seed/01_academics_timetable_seed.sql. MySQL original is unchanged.
-- Generated by db/tools/generate_seeds.py - do not edit by hand.
-- Faculty assigned to every offering + the weekly timetable of the TY E&TC divisions (SAMPLE).
SELECT set_config('seed.sem_cur', (fn_current_semester())::TEXT, false);
SELECT set_config('seed.sem_prev', ((SELECT s.semester_id FROM semester s JOIN academic_year ay ON ay.academic_year_id = s.academic_year_id WHERE ay.label = '2025-26' AND s.term = 'EVEN'))::TEXT, false);

CREATE TEMPORARY TABLE tmp_assign (course_code VARCHAR(8), division_name VARCHAR(20) NULL, sem_kind VARCHAR(4), employee_id CHAR(7));

UPDATE course_offering o
   SET employee_id = a.employee_id
  FROM tmp_assign a
WHERE a.course_code = o.course_code
  AND o.semester_id = CASE WHEN a.sem_kind = 'CUR' THEN current_setting('seed.sem_cur')::INTEGER ELSE current_setting('seed.sem_prev')::INTEGER END
  AND ((a.division_name IS NULL AND o.division_id IS NULL) OR a.division_name = (SELECT d.division_name FROM division d WHERE d.division_id = o.division_id));

CREATE TEMPORARY TABLE tmp_slot (course_code VARCHAR(8), division_name VARCHAR(20) NULL, classroom_code VARCHAR(10), batch_code VARCHAR(5) NULL, day_of_week VARCHAR(3), start_time TIME, end_time TIME, slot_type VARCHAR(10));

-- trg_timetable_clash validates every row of this insert
SELECT o.offering_id, c.classroom_id, o.employee_id, b.batch_id, t.day_of_week, t.start_time, t.end_time, t.slot_type
  FROM tmp_slot t
  JOIN course_offering o ON o.course_code = t.course_code AND o.semester_id = current_setting('seed.sem_cur')::INTEGER
  LEFT JOIN division d   ON d.division_id = o.division_id
  JOIN classroom c       ON c.classroom_code = t.classroom_code
  LEFT JOIN batch b      ON b.batch_code = t.batch_code AND b.division_id = d.division_id
 WHERE (t.division_name IS NULL AND o.division_id IS NULL) OR d.division_name = t.division_name
 ORDER BY o.offering_id, t.day_of_week, t.start_time, t.batch_code;

DROP TABLE tmp_assign;
DROP TABLE tmp_slot;
